"    <script>
let currentProcessId = null;
let selectedWarehouseFiles = [];
let selectedShortageFiles = [];
let serverStatusInterval = null;
let isServerRunning = false;

// Ensure Pywebview API is ready
window.addEventListener('pywebviewready', function() {
    loadSettings();
    loadLogs();
    updateServerStatus();
    serverStatusInterval = setInterval(updateServerStatus, 5000);
    setupDragAndDrop();
});

// Logs Logic
window.addEventListener('new_log', function(e) {
    const logArea = document.getElementById('system-logs');
    if (logArea) {
        logArea.value += e.detail + '\n';
        logArea.scrollTop = logArea.scrollHeight;
    }
});

async function loadLogs() {
    try {
        const logsStr = await window.pywebview.api.get_logs();
        const logs = JSON.parse(logsStr);
        const logArea = document.getElementById('system-logs');
        if (logArea) {
            logArea.value = logs.join('\n') + (logs.length ? '\n' : '');
            logArea.scrollTop = logArea.scrollHeight;
        }
    } catch (e) {
        console.error(e);
    }
}

// Toast Notifications
function showToast(message, type = 'success') {
    const container = document.getElementById('toast-container');
    const toast = document.createElement('div');
    toast.className = `toast ${type}`;

    const icon = type === 'success' ? 'ph-check-circle' : 'ph-warning-circle';
    toast.innerHTML = `<i class="ph-fill ${icon}"></i> <span>${message}</span>`;

