    def add_log(self, message: str):
        self.logs.append(message)
        if len(self.logs) > 1000:
            self.logs.pop(0)

        if self.window:
            try:
                safe_msg = message.replace("'", "\\'").replace('\n', '\\n').replace('\r', '')
                self.window.evaluate_js(f"window.dispatchEvent(new CustomEvent('new_log', {{detail: '{safe_msg}'}}));")
            except:
                pass

    def get_logs(self) -> str:
        return json.dumps(self.logs)

    def get_dropped_files(self) -> str:
        """Called by JS to retrieve the list of files dropped."""
        files = self.dropped_files
        self.dropped_files = []
        return json.dumps(files)

    def exit_app(self):
        try:
            self.on_closing()
        except:
            pass
        # os._exit guarantees immediate shutdown without blocking background threads like uvicorn
        os._exit(0)"

