"function updateFileList(type, files) {
    const listEl = document.getElementById(`list-${type}`);
    listEl.innerHTML = '';
    files.forEach((path, index) => {
        let fileName = path.split('\\').pop().split('/').pop();
        if (fileName.includes('?')) {
            fileName = fileName.split('?')[0];
        }

        let iconClass = 'ph-file';
        const ext = fileName.split('.').pop().toLowerCase();
        if (ext === 'pdf') iconClass = 'ph-file-pdf text-danger';
        else if (ext === 'xlsx' || ext === 'xls' || ext === 'csv') iconClass = 'ph-file-xls text-success';
        else if (ext === 'json') iconClass = 'ph-file-code text-warning';

        const li = document.createElement('li');
        li.className = 'file-item';
        li.innerHTML = `
            <div class="file-item-name" title="${path}">
                <i class="ph-fill ${iconClass}"></i>
                <span>${fileName}</span>
            </div>
            <button class="file-item-delete" onclick="removeFile('${type}', ${index})" title="إزالة الملف">
                <i class="ph-fill ph-trash"></i>
            </button>
        `;
        listEl.appendChild(li);
    });
}"

