    try {
        const historyStr = await window.pywebview.api.get_history();
        const history = JSON.parse(historyStr);

        if (!history || history.length === 0) {
            listEl.innerHTML = '<div class="empty-state"><i class="ph-fill ph-empty"></i><p>لا توجد عمليات سابقة مسجلة.</p></div>';
