function exitApp() {
    if (window.activeProcesses > 0) {
        showCustomConfirm('تأكيد الإغلاق', 'توجد عمليات مطابقة قيد التشغيل في الخلفية. هل أنت متأكد من الإغلاق؟', async () => {
            try {
                if (window.pywebview && window.pywebview.api) {
                    await window.pywebview.api.exit_app();
                }
            } catch (e) {
                console.error(e);
            }
        });
    } else {
        try {
            if (window.pywebview && window.pywebview.api) {
                window.pywebview.api.exit_app();
            }
        } catch (e) {
            console.error(e);
        }
    }
}

// Delete Process
function deleteProcess(processId) {
    showCustomConfirm('تأكيد الحذف', 'هل أنت متأكد من حذف هذه العملية نهائياً من السجل؟', async () => {
        try {
            const res = await window.pywebview.api.delete_process(processId);
            if (res.success) {
                showToast('تم الحذف بنجاح', 'success');
                loadHistory();
            } else {
                showToast('خطأ: ' + res.error, 'error');
            }
        } catch (error) {
            showToast('خطأ في الحذف', 'error');
        }
    });
}"

