"// Exit App
async function exitApp() {
    try {
        let isRunning = false;
        if (window.pywebview && window.pywebview.api) {
            const historyStr = await window.pywebview.api.get_history();
            const history = JSON.parse(historyStr);
            isRunning = history.some(item => item.status === 'processing');
        }

        if (isRunning) {
            showCustomConfirm('تأكيد الإغلاق', 'توجد عمليات مطابقة قيد التشغيل في الخلفية. هل أنت متأكد من الإغلاق؟', async () => {
                await window.pywebview.api.exit_app();
            });
        } else {
            if (window.pywebview && window.pywebview.api) {
                await window.pywebview.api.exit_app();
            }
        }
    } catch (e) {
        console.error(e);
        // Fallback
        if (window.pywebview && window.pywebview.api) {
            window.pywebview.api.exit_app();
        }
    }
}"

