"async function restartProcess(processId) {
    try {
        const res = await window.pywebview.api.restart_process(processId);
        if (res.success) {
            currentProcessId = res.process_id;
            switchScreen('screen-new');

            const btn = document.getElementById('btn-submit');
            const progressModal = document.getElementById('progress-modal');

            btn.classList.add('hidden');
            progressModal.style.display = 'flex';
            document.getElementById('progress-text').innerText = 'جاري تهيئة العملية...';
            document.getElementById('progress-bar-fill').style.width = '5%';

            const termEl = document.getElementById('pipeline-log-terminal');
            if (termEl) termEl.innerHTML = `[System] Restarted process ${processId}...\n`;

            showToast('تم بدء العملية من جديد', 'success');
        } else {
            showToast(res.error || 'حدث خطأ أثناء إعادة التشغيل', 'error');
        }
    } catch (e) {
        showToast('خطأ في الاتصال بالبرنامج', 'error');
        console.error(e);
    }
}

