            for item in d.get("items", []):
                if not isinstance(item, dict):
                    continue
                name = item.get("item_name_raw")
                if name:
                    items.append({
                        "item_name_raw": str(name).strip(),
                        "source_page": item.get("source_page"),
                        "source_file": filename
                    })
    return items

