"// Exit App
async function exitApp() {
    const t = I18N[currentLang] || I18N.ar;
    try {
        let isRunning = false;
        if (window.pywebview && window.pywebview.api) {
            const historyStr = await window.pywebview.api.get_history();
            const history = JSON.parse(historyStr);
            isRunning = history.some(item => item.status === 'processing');
        }

        if (isRunning) {
            showCustomConfirm(t.confirm_exit_title, t.confirm_exit_msg, async () => {
                await window.pywebview.api.exit_app();
            });
        } else {
            if (window.pywebview && window.pywebview.api) {
                await window.pywebview.api.exit_app();
            }
        }
    } catch (e) {
        console.error(e);
        // Fallback
        if (window.pywebview && window.pywebview.api) {
            window.pywebview.api.exit_app();
        }
    }
}

// Delete Process
function deleteProcess(processId) {
    const t = I18N[currentLang] || I18N.ar;
    showCustomConfirm(t.confirm_delete_title, t.confirm_delete_msg, async () => {
        try {
            const res = await window.pywebview.api.delete_process(processId);
            if (res.success) {
                showToast(t.toast_deleted, 'success');
                loadHistory();
            } else {
                showToast((currentLang === 'en' ? 'Error: ' : 'خطأ: ') + res.error, 'error');
            }
        } catch (error) {
            showToast(currentLang === 'en' ? 'Deletion error' : 'خطأ في الحذف', 'error');
        }
    });
}"

