"import subprocess
import os
import signal
import time
import sys
import threading
from pathlib import Path

class MSEMAXServerManager:
    def __init__(self, msemax_dir: str, logger_callback=None):
        self.msemax_dir = msemax_dir
        self.process = None
        self.logger = logger_callback

    def log(self, message):
        if self.logger:
            self.logger(message)
        else:
            print(message)

    def is_running(self) -> bool:
        if self.process is None:
            return False
        return self.process.poll() is None

    def _read_output(self, pipe, prefix):
        try:
            for line in iter(pipe.readline, ''):
                if line:
                    self.log(f"{prefix} {line.strip()}")
        except Exception:
            pass
        finally:
            pipe.close()

    def start(self) -> dict:
        if self.is_running():
            self.log("[SYSTEM] Server is already running.")
            return {"success": True, "message": "already running"}

        try:
            creationflags = 0
            if os.name == 'nt':
                creationflags = subprocess.CREATE_NO_WINDOW

            self.log("[SYSTEM] Starting MSEMAX Server...")
            self.process = subprocess.Popen(
                [sys.executable, "app.py"],
                cwd=self.msemax_dir,
                creationflags=creationflags,
                stdout=subprocess.PIPE,
                stderr=subprocess.STDOUT,
                text=True,
                bufsize=1
            )

            t = threading.Thread(target=self._read_output, args=(self.process.stdout, "[SERVER]"), daemon=True)
            t.start()

            self.log("[SYSTEM] Server process started successfully.")
            return {"success": True, "message": "started"}
        except Exception as e:
            self.log(f"[SYSTEM ERROR] Failed to start server: {str(e)}")
