"    // Update active server labels across the UI
    try {
        if (window.pywebview && window.pywebview.api) {
            const infoStr = await window.pywebview.api.get_servers_info();
            const info = JSON.parse(infoStr);
            const activeKey = info.active_server || 'gaistudio';
            const activeSrv = info.servers?.[activeKey];
            if (activeSrv) {
                const shortName = activeKey === 'gaistudio' ? 'Google AI Studio (8001)' : 'ChatGPT (8000)';
                const sidebarName = document.getElementById('sidebar-active-server-name');
                if (sidebarName) sidebarName.textContent = shortName;

                const homeText = document.getElementById('home-active-server-text');
                if (homeText) {
                    homeText.textContent = currentLang === 'en'
                        ? `Active Matching Server: ${shortName} • ${activeSrv.default_model || ''}`
                        : `سيرفر المطابقة النشط: ${shortName} • ${activeSrv.default_model || ''}`;
                }

                const topText = document.getElementById('top-bar-server-text');
                if (topText) {
                    topText.textContent = `${shortName}: ` + (isRunning ? t.server_running : t.server_stopped);
                }
            }
        }
    } catch (e) {
        console.error('Error updating active server label:', e);
    }

    // Update top bar server badge
    const topBadge = document.getElementById('top-bar-server-badge');
    if (topBadge) {
        topBadge.className = isRunning ? 'server-badge-pill running' : 'server-badge-pill stopped';
    }

    // Also auto-refresh servers screen if it is active
    const srvScreen = document.getElementById('screen-servers');
    if (srvScreen && srvScreen.classList.contains('active')) {
        loadServersUI();
    }
}"

