import subprocess
res = subprocess.run('netstat -ano', shell=True, capture_output=True, text=True)
pids = set()
for l in res.stdout.splitlines():
    if ':8000' in l and 'LISTENING' in l:
        parts = l.split()
        if parts: pids.add(parts[-1])
print('Killing:', pids)
for p in pids:
    subprocess.run(['taskkill', '/F', '/T', '/PID', str(p)], capture_output=True)
print('Done!')
""

