"async function clearServerLogs() {
    const term = document.getElementById('ai-server-terminal');
    if (term) term.value = '';
    try {
        if (window.pywebview?.api?.clear_server_logs) {
            await window.pywebview.api.clear_server_logs();
        }
        showToast(currentLang === 'en' ? 'Server logs cleared' : 'تم مسح سجل السيرفرات بنجاح', 'success');
    } catch (e) {
        console.error(e);
    }
}

async function freeServerPorts() {
    showToast(currentLang === 'en' ? 'Freeing ports 8000 & 8001...' : 'جاري تحرير المنافذ 8000 و 8001...', 'info');
    appendServerLog('[SYSTEM] Initiating force free ports 8000 and 8001...');
    try {
        const res = await window.pywebview.api.free_server_ports();
        appendServerLog(`[SYSTEM] Free ports operation completed: ${JSON.stringify(res)}`);
        if (res && res.elevated_needed) {
            showToast(currentLang === 'en' 
                ? 'Requested Administrator privileges to terminate zombie processes.' 
                : 'تم طلب صلاحيات المسؤول لإغلاق العمليات المعلقة. يرجى تأكيد نافذة UAC إذا ظهرت.', 'warning');
        } else {
            showToast(currentLang === 'en' ? 'Ports freed successfully!' : 'تم فحص وتحرير المنافذ بنجاح!', 'success');
        }
    } catch (e) {
        appendServerLog(`[ERROR] Failed to free ports: ${e.message}`);
        showToast(currentLang === 'en' ? 'Error freeing ports' : 'حدث خطأ أثناء تحرير المنافذ', 'error');
    } finally {
        setTimeout(async () => {
            await loadServersUI();
            await updateServerStatus();
        }, 1500);
    }
}"

