"def format_messages_to_prompt(messages: List[ChatMessage]) -> str:
    """Combines user/system/assistant messages into a clean prompt string."""
    system_lines = []
    dialogue_lines = []

    for m in messages:
        content = m.content or ""
        if isinstance(content, list):
            content = " ".join([p.get("text", "") for p in content if isinstance(p, dict) and "text" in p])
        content = str(content).strip()
        if not content:
            continue

        if m.role == "system":
            system_lines.append(content)
        elif m.role == "user":
            dialogue_lines.append(f"User: {content}")
        elif m.role == "assistant":
            dialogue_lines.append(f"Assistant: {content}")

    # In continuous chat mode where CLEAR_CHAT_ON_REQUEST is False,
    # previous assistant/user turns already live in the browser session.
    # But system instructions must ALWAYS be preserved if provided.
    if not CLEAR_CHAT_ON_REQUEST and dialogue_lines:
        last_user = dialogue_lines[-1].replace("User: ", "", 1)
        if system_lines:
            return f"[System Instructions]\n" + "\n\n".join(system_lines) + "\n\n" + last_user
        return last_user

    parts = []
    if system_lines:
        parts.append("[System Instructions]\n" + "\n\n".join(system_lines))

    if len(dialogue_lines) == 1:
        # Clean single user prompt without "User:" prefix
        parts.append(dialogue_lines[0].replace("User: ", "", 1))
    elif dialogue_lines:
        parts.append("\n\n".join(dialogue_lines))

    return "\n\n".join(parts)"

