            if m.role == "system" and m.content
        ]
        if system_lines and len(messages) <= 2:
            return f"[System Instructions]\n" + "\n".join(system_lines) + "\n\n" + last_user
        if last_user:
            return last_user

    system_lines = []
    dialogue_lines = []

    for m in messages:
        content = m.content or ""
        if isinstance(content, list):
            content = " ".join([p.get("text", "") for p in content if isinstance(p, dict) and "text" in p])
        content = str(content).strip()

        if m.role == "system":
            system_lines.append(content)
        elif m.role == "user":
            dialogue_lines.append(f"User: {content}")
        elif m.role == "assistant":
            dialogue_lines.append(f"Assistant: {content}")

    if len(dialogue_lines) == 1 and not system_lines:
        return dialogue_lines[0].replace("User: ", "", 1)

    parts = []
    if system_lines:
        parts.append("[System Instructions]\n" + "\n".join(system_lines))
    if dialogue_lines:
        parts.append("\n".join(dialogue_lines))

    return "\n\n".join(parts)"

