DEFAULT_MODEL = os.environ.get("LOCAL_MODEL", "gemini-3.8-flash")


def request_body(model, inputs):
    return {
        "model": model or DEFAULT_MODEL,
        "messages": [
            {
                "role": "system",
                "content": SYSTEM + "\nReturn ONLY one JSON object conforming to this schema, without markdown:\n" + json.dumps(response_schema())
            },
            {
                "role": "user",
                "content": json.dumps(inputs, ensure_ascii=False)
            }
        ],
        "stream": False
    }


def as_report_response(raw):
    return normalize_response(raw, "Local_MSEMAX")
