"import sys
import time
import requests
import subprocess
from pathlib import Path

PYTHON_EXE = r"D:\miniconda3\envs\venv\python.exe"

def test():
    print(f"Starting MSEMAX using: {PYTHON_EXE}")
    p = subprocess.Popen([PYTHON_EXE, "app.py"], cwd=r"D:\AI_Engineer\MSEMAX")
    print(f"Process spawned with PID {p.pid}")

    # Wait for server
    healthy = False
    for i in range(10):
        time.sleep(1)
        try:
            r = requests.get("http://127.0.0.1:8000/health", timeout=1)
            if r.status_code == 200:
                print(f"Server healthy after {i+1}s: {r.json()}")
                healthy = True
                break
        except Exception:
            print(f"Waiting {i+1}s...")

    if not healthy:
        print("Server failed to become healthy.")
    else:
        # Test chat completion endpoint
        payload = {
            "model": "gpt-4o",
            "messages": [{"role": "user", "content": "Reply with only PONG"}],
            "stream": False
        }
        headers = {
            "Authorization": "Bearer [REDACTED_CREDENTIAL]",
            "Content-Type": "application/json"
        }
        try:
            r = requests.post("http://127.0.0.1:8000/v1/chat/completions", json=payload, headers=headers, timeout=20)
            print("Chat completion status:", r.status_code)
            print("Response:", r.text[:300])
        except Exception as e:
            print("Chat completion error:", e)

    print("Terminating process...")
    p.terminate()
    try:
        p.wait(timeout=3)
    except:
        p.kill()
    print("Done.")

if __name__ == "__main__":
    test()
"

