"        // Override showScreen to handle active states on sidebar
        const originalShowScreen = window.showScreen;
        window.showScreen = function(screenId, element = null) {
            // Call original if it exists
            if (typeof originalShowScreen === 'function') {
                originalShowScreen(screenId);
            } else {
                document.querySelectorAll('.screen').forEach(s => s.classList.remove('active'));
                const target = document.getElementById(screenId);
                if (target) target.classList.add('active');
            }

            // Auto-detect and sync sidebar active nav item if element is null or not provided
            if (!element) {
                element = document.querySelector(`.nav-menu .nav-item[onclick*="${screenId}"]`);
            }
            if (element) {
                document.querySelectorAll('.nav-item').forEach(btn => btn.classList.remove('active'));
                element.classList.add('active');
            }

            // Update top bar heading
            if (typeof updateTopBarHeading === 'function') {
                updateTopBarHeading(screenId);
            }

            if (screenId === 'screen-new') {
                if (typeof isProcessRunning !== 'undefined' && isProcessRunning) {
                    const progressModal = document.getElementById('progress-modal');
                    if (progressModal) progressModal.style.display = 'flex';
                } else {
                    resetNewProcessForm();
                }
            } else if (screenId === 'screen-logs' || screenId === 'screen-settings') {
                loadLogs();
            } else if (screenId === 'screen-servers') {
                loadServersUI();
                loadServerLogs();
            }
        };"

