"function startProgressTimer() {
    progressStartTime = Date.now();
    const timerEl = document.getElementById('progress-timer');
    if (timerEl) timerEl.textContent = '⏱️ 00:00';
    clearInterval(progressTimerInterval);
    progressTimerInterval = setInterval(() => {
        const elapsed = Math.floor((Date.now() - progressStartTime) / 1000);
        const mins = String(Math.floor(elapsed / 60)).padStart(2, '0');
        const secs = String(elapsed % 60).padStart(2, '0');
        if (timerEl) timerEl.textContent = `⏱️ ${mins}:${secs}`;
    }, 1000);
    const screenNew = document.getElementById('screen-new');
    if (screenNew) {
        screenNew.scrollTop = 0;
        screenNew.style.overflowY = 'hidden';
    }
}

function stopProgressTimer() {
    clearInterval(progressTimerInterval);
    progressTimerInterval = null;
    const screenNew = document.getElementById('screen-new');
    if (screenNew) {
        screenNew.style.overflowY = 'auto';
    }
}"

